import axios from 'axios'
export default {
    data(){
        return{
            dialog: false,
            search:'',
            personas:[],
            headers: [
                { text: 'Opciones', value: 'opciones', sortable: false },
                { text: 'Codigo', value: 'CodigoCliente', sortable: true },
                { text: 'Razon Social', value: 'RazonSocial', sortable: true },
                { text: 'Cedula', value: 'Cedula', sortable: true },
                { text: 'RUC', value: 'Ruc', sortable: false  },
                { text: 'Dirección', value: 'Direccion', sortable: false  },
                { text: 'Teléfono', value: 'Telefono', sortable: false  },
                { text: 'Email', value: 'Email', sortable: false  },
                { text: 'Ciudad', value: 'Ciudad', sortable: false  } 
            ],
            editedIndex: -1,
            _id:'',
            RazonSocial:'',
            Cedula:'',
            Ruc:'',
            Direccion: '',
            Telefono: '',
            Ciudad: '',
            Email: '',
            valida:0,
            validaMensaje:[],
            adModal:0,
            adAccion:0,
            adNombre:'',
            adId:''
        }
    },
    computed: {
        formTitle () {
        return this.editedIndex === -1 ? 'Nuevo registro' : 'Editar registro'
        }
    },
    watch: {
        dialog (val) {
        val || this.close()
        }
    },
    created () {
        this.listar()
    },
    methods: {
        listar(){
            let me=this;         
            axios.get('clientes/').then(function (response){
                me.personas=response.data;
            }).catch(function(error){
                console.log(error);
            });

        },
        limpiar(){
            this._id='';
            this.nombre='';
            this.num_documento='';
            this.direccion='';
            this.telefono='';
            this.email='';
            this.valida=0;
            this.validaMensaje=[];
            this.editedIndex=-1;
        },
        validar(){
            this.valida=0;
            this.validaMensaje=[];
            if(this.nombre.length<1 || this.nombre.length>50){
                this.validaMensaje.push('El nombre de la persona debe tener entre 1-50 caracteres.');
            }
            if(this.num_documento.length>20){
                this.validaMensaje.push('El documento no debe tener más de 20 caracteres.');
            }
            if(this.direccion.length>70){
                this.validaMensaje.push('La dirección no debe tener más de 70 caracteres.');
            }
            if(this.telefono.length>20){
                this.validaMensaje.push('El teléfono no debe tener más de 20 caracteres.');
            }
            if(this.nombre.length>50){
                this.validaMensaje.push('El email del usuario debe tener menos de 50 caracteres.');
            }
            if (this.validaMensaje.length){
                this.valida=1;
            }
            return this.valida;
        },
        guardar(){
            let me=this;
            let header={"Token" : this.$store.state.token};
            let configuracion= {headers : header};
            if (this.validar()){
                return;
            }
            if (this.editedIndex >-1){
                //Código para editar
                axios.put('persona/update',{
                    '_id':this._id,
                    'tipo_persona':this.tipo_persona,
                    'nombre':this.nombre,
                    'tipo_documento':this.tipo_documento,
                    'num_documento':this.num_documento,
                    'direccion':this.direccion,
                    'telefono': this.telefono,
                    'email':this.email
                },configuracion)
                .then(function(response){
                    me.limpiar();
                    me.close();
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
            }else{
                //Código para guardar
                axios.post('persona/add',
                {
                    'tipo_persona':this.tipo_persona,
                    'nombre':this.nombre,
                    'tipo_documento':this.tipo_documento,
                    'num_documento':this.num_documento,
                    'direccion':this.direccion,
                    'telefono': this.telefono,
                    'email':this.email
                },configuracion)
                .then(function(response){
                    me.limpiar();
                    me.close();
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
            }
        },
        editItem (item) {
            this._id=item._id;
            this.rol=item.rol;
            this.nombre=item.nombre;
            this.tipo_documento=item.tipo_documento;
            this.num_documento=item.num_documento;
            this.direccion=item.direccion;
            this.telefono=item.telefono;
            this.email=item.email;
            this.password=item.password;
            this.dialog = true;
            this.editedIndex=1;
        },
        activarDesactivarMostrar(accion,item){
            this.adModal=1;
            this.adNombre=item.nombre;
            this.adId=item._id;
            if (accion==1){
                this.adAccion=1;
            } else if(accion==2){
                this.adAccion=2;
            } else{
                this.adModal=0;
            }
        },
        activarDesactivarCerrar(){
            this.adModal=0;
        },
        activar(){
            let me=this;
            let header={"Token" : this.$store.state.token};
            let configuracion= {headers : header};
            axios.put('persona/activate',{'_id':this.adId},configuracion)
                .then(function(response){
                    me.adModal=0;
                    me.adAccion=0;
                    me.adNombre='';
                    me.adId='';
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
        },
        desactivar(){
            let me=this;
            let header={"Token" : this.$store.state.token};
            let configuracion= {headers : header};
            axios.put('persona/deactivate',{'_id':this.adId},configuracion)
                .then(function(response){
                    me.adModal=0;
                    me.adAccion=0;
                    me.adNombre='';
                    me.adId='';
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
        },
        close () {
            this.dialog = false;
        }
    }
}
